const journalGoldenWire = ""

type journalVariant struct {
	name string
	edit func(*registeredGenesisSource)
	wire string
}

func journalHex(t *testing.T, text string) []byte {
	t.Helper()
	out, err := hex.DecodeString(text)
	if err != nil {
		t.Fatalf("independent hex: %v", err)
	}
	return out
}

var journalGoldenSource = registeredGenesisSource{
	Scope:      raftlog.ApplicationIdentity{Graph: [16]byte{1}, Partition: 1, Group: [16]byte{2}},
	SourceKind: 1, SourcePosition: 1, SourceTerm: 1, ImageLength: 140,
	ImageHash:         [32]byte{0x12, 0xcf, 0x5d, 0x25, 0x76, 0x54, 0xd0, 0xfa, 0x37, 0x79, 0xb2, 0xb4, 0x02, 0x6d, 0x83, 0x84, 0x40, 0xec, 0x14, 0xe6, 0x5c, 0x1a, 0xd4, 0xab, 0xda, 0x97, 0x08, 0x0e, 0xcc, 0x01, 0xf8, 0x6a},
	InitialOwnerEpoch: 1, Voters: [3]uint64{1, 2, 3},
	Meaning:        [32]byte{0x35, 0x80, 0x26, 0xa0, 0x48, 0xd7, 0x2e, 0x4d, 0xe7, 0x03, 0xda, 0x15, 0x63, 0x69, 0x11, 0x7d, 0x06, 0xcf, 0xa1, 0x87, 0x7d, 0xa8, 0x22, 0x91, 0xf3, 0xd2, 0x34, 0x16, 0xaf, 0xd9, 0x62, 0x6d},
	SharedContract: [10]uint64{2, 1024, 1048576, 65536, 4096, 2097152, 4096, 4194304, 1048576, 65536},
}

func checkJournalGolden(t *testing.T, source registeredGenesisSource, want []byte) ([]byte, []byte, registeredGenesisSource) {
	t.Helper()
	budget := registeredJournalBudget{walkBytes: 33554432}
	encoded, err := encodeGenesisSource(source, budget)
	checkJournalResult(t, err, nil, bytes.Equal(encoded, want[11:]) && cap(encoded) == 244)
	wire, err := encodeGenesisCommand(source, budget)
	checkJournalResult(t, err, nil, bytes.Equal(wire, want) && cap(wire) == 255)
	decoded, err := decodeGenesisCommand(want, budget)
	checkJournalResult(t, err, nil, decoded == source)
	return encoded, wire, decoded
}
func checkJournalResult(t *testing.T, got, want error, correct bool) {
	t.Helper()
	if !errors.Is(got, want) || !correct {
		t.Fatalf("journal result: err%v want%v correctOutput%t", got, want, correct)
	}
}
func TestRegisteredJournalGenesisFixture(t *testing.T) {
	checkJournalGolden(t, journalGoldenSource, journalHex(t, journalGoldenWire))
}
func TestRegisteredJournalIndependentVariants(t *testing.T) {
	cases := []journalVariant{
		{"opaque-zero-hash", func(s *registeredGenesisSource) { s.ImageHash = [32]byte{} }, ""},
		{"opaque-alternate-hash", func(s *registeredGenesisSource) { s.ImageHash = [32]byte{9} }, ""},
		{"scope", func(s *registeredGenesisSource) {
			s.Scope = raftlog.ApplicationIdentity{Graph: [16]byte{5}, Partition: 7, Group: [16]byte{6}}
		}, ""},
		{"meaning", func(s *registeredGenesisSource) { s.Meaning = [32]byte{8} }, ""},
		{"owner-epoch", func(s *registeredGenesisSource) { s.InitialOwnerEpoch = 9 }, ""},
		{"ordered-voters", func(s *registeredGenesisSource) { s.Voters = [3]uint64{4, 5, 6} }, ""},
		{"contract-minimum", func(s *registeredGenesisSource) { s.SharedContract = [10]uint64{2, 1, 1, 140, 1, 1, 1, 1, 1, 1} }, ""},
		{"contract-maximum", func(s *registeredGenesisSource) {
			s.SharedContract = [10]uint64{2, 65536, 16777216, 67108864, 4096, 67108864, 4096, 67108864, 67108864, 67108864}
		}, ""},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			s := journalGoldenSource
			tc.edit(&s)
			checkJournalGolden(t, s, journalHex(t, tc.wire))
		})
	}
}
func TestRegisteredJournalInvalidSourceFields(t *testing.T) {
	cases := []journalVariant{
		{"kind-0", func(s *registeredGenesisSource) { s.SourceKind = 0 }, ""},
		{"kind-2", func(s *registeredGenesisSource) { s.SourceKind = 2 }, ""},
		{"position-0", func(s *registeredGenesisSource) { s.SourcePosition = 0 }, ""},
		{"position-2", func(s *registeredGenesisSource) { s.SourcePosition = 2 }, ""},
		{"term-0", func(s *registeredGenesisSource) { s.SourceTerm = 0 }, ""},
		{"term-2", func(s *registeredGenesisSource) { s.SourceTerm = 2 }, ""},
		{"image_length-0", func(s *registeredGenesisSource) { s.ImageLength = 0 }, ""},
		{"image_length-139", func(s *registeredGenesisSource) { s.ImageLength = 139 }, ""},
		{"image_length-141", func(s *registeredGenesisSource) { s.ImageLength = 141 }, ""},
		{"zero-graph", func(s *registeredGenesisSource) { s.Scope.Graph = [16]byte{} }, ""},
		{"zero-group", func(s *registeredGenesisSource) { s.Scope.Group = [16]byte{} }, ""},
		{"zero-meaning", func(s *registeredGenesisSource) { s.Meaning = [32]byte{} }, ""},
		{"zero-partition", func(s *registeredGenesisSource) { s.Scope.Partition = 0 }, ""},
		{"zero-epoch", func(s *registeredGenesisSource) { s.InitialOwnerEpoch = 0 }, ""},
		{"zero-voter-0", func(s *registeredGenesisSource) { s.Voters[0] = 0 }, ""},
		{"zero-voter-1", func(s *registeredGenesisSource) { s.Voters[1] = 0 }, ""},
		{"zero-voter-2", func(s *registeredGenesisSource) { s.Voters[2] = 0 }, ""},
		{"reserved-voter-18446744073709551615", func(s *registeredGenesisSource) { s.Voters[2] = 18446744073709551615 }, ""},
		{"reserved-voter-18446744073709551614", func(s *registeredGenesisSource) { s.Voters[2] = 18446744073709551614 }, ""},
		{"duplicate-voters", func(s *registeredGenesisSource) { s.Voters = [3]uint64{1, 1, 3} }, ""},
		{"unordered-voters", func(s *registeredGenesisSource) { s.Voters = [3]uint64{3, 2, 1} }, ""},
		{"contract-special-1-65537", func(s *registeredGenesisSource) { s.SharedContract[1] = 65537 }, ""},
		{"contract-special-2-16777217", func(s *registeredGenesisSource) { s.SharedContract[2] = 16777217 }, ""},
		{"contract-special-4-4097", func(s *registeredGenesisSource) { s.SharedContract[4] = 4097 }, ""},
		{"contract-special-6-4097", func(s *registeredGenesisSource) { s.SharedContract[6] = 4097 }, ""},
		{"contract-special-3-139", func(s *registeredGenesisSource) { s.SharedContract[3] = 139 }, ""},
	}
	good := journalHex(t, journalGoldenWire)
	for field := range 10 {
		values := []uint64{0, 67108865, 18446744073709551615}
		if field == 0 {
			values = []uint64{0, 1, 3}
		}
		for _, value := range values {
			wire := bytes.Clone(good)
			binary.BigEndian.PutUint64(wire[175+8*field:], value)
			cases = append(cases, journalVariant{fmt.Sprintf("contract-%d-%d", field, value), func(s *registeredGenesisSource) { s.SharedContract[field] = value }, hex.EncodeToString(wire)})
		}
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			s := journalGoldenSource
			tc.edit(&s)
			budget := registeredJournalBudget{walkBytes: 33554432}
			for _, encode := range []func(registeredGenesisSource, registeredJournalBudget) ([]byte, error){encodeGenesisSource, encodeGenesisCommand} {
				out, err := encode(s, budget)
				checkJournalResult(t, err, errInvalid, out == nil)
			}
			out, err := decodeGenesisCommand(journalHex(t, tc.wire), budget)
			checkJournalResult(t, err, errInvalid, out == (registeredGenesisSource{}))
		})
	}
}
func TestRegisteredJournalInvalidWire(t *testing.T) {
	good := journalHex(t, journalGoldenWire)
	reject := func(wire []byte) {
		out, err := decodeGenesisCommand(wire, registeredJournalBudget{walkBytes: 33554432})
		checkJournalResult(t, err, errInvalid, out == (registeredGenesisSource{}))
	}
	reject(append(bytes.Clone(good), 0))
	for i := range len(good) {
		reject(good[:i])
	}
	for _, change := range []struct {
		at    int
		value byte
	}{{0, 0}, {3, 2}, {4, 1}, {5, 0}, {5, 2}, {6, 1}, {6, 128}, {6, 255}, {7, 1}, {8, 1}, {9, 1}, {10, 0}, {10, 243}, {10, 245}, {11, 0}, {14, 2}, {15, 1}, {16, 0}, {16, 2}, {118, 0}, {118, 2}, {118, 4}, {118, 255}} {
		wire := bytes.Clone(good)
		wire[change.at] = change.value
		reject(wire)
	}
}
func TestRegisteredJournalLedgerAndOwnership(t *testing.T) {
	budgetErrors := [5]error{errLimit, nil, nil, errInvalid, errInvalid}
	source := journalGoldenSource
	good := journalHex(t, journalGoldenWire)
	for _, op := range []struct {
		need   uint64
		want   []byte
		encode func(registeredGenesisSource, registeredJournalBudget) ([]byte, error)
	}{{3292, good[11:], encodeGenesisSource}, {3314, good, encodeGenesisCommand}} {
		for i, allowance := range []uint64{op.need - 1, op.need, op.need + 1, 0, 33554433} {
			out, err := op.encode(source, registeredJournalBudget{walkBytes: allowance})
			wantErr := budgetErrors[i]
			correct := out == nil
			if wantErr == nil {
				correct = bytes.Equal(out, op.want) && cap(out) == len(op.want)
			}
			checkJournalResult(t, err, wantErr, correct)
		}
	}
	for i, allowance := range []uint64{3058, 3059, 3060, 0, 33554433} {
		out, err := decodeGenesisCommand(good, registeredJournalBudget{walkBytes: allowance})
		wantErr := budgetErrors[i]
		want := source
		if wantErr != nil {
			want = registeredGenesisSource{}
		}
		checkJournalResult(t, err, wantErr, out == want)
	}
	input := bytes.Clone(good)
	a, b, decoded := checkJournalGolden(t, source, input)
	a2, b2, _ := checkJournalGolden(t, source, good)
	a[0] ^= 255
	b[0] ^= 255
	clear(input)
	if !bytes.Equal(a2, good[11:]) || !bytes.Equal(b2, good) || decoded != source || source != journalGoldenSource {
		t.Fatal("aliased outputs/decoded input or mutated source")
	}
}
